import "server-only";

import { gunzipSync } from "node:zlib";

import {
  EMBEDDED_DATA_GLOBAL_KEY,
  type EmbeddedDataBundle,
} from "./embedded-bundle";
import { EMBEDDED_DATA_GZIP_BASE64 } from "../../../.data-bundle/embedded-data.generated";

/**
 * Installs the build-time data bundle for a runtime without a filesystem.
 *
 * This is the ONLY module that imports the generated bytes. Keeping the import
 * in the instrumentation entry is what stops the bundler from duplicating the
 * corpus into every route chunk that reaches a loader; see
 * `embedded-bundle.ts` for the measurement behind that decision.
 *
 * Idempotent: `register()` may be called more than once (hot reload, duplicate
 * invocation) and must not re-inflate and re-parse the corpus each time.
 * Decoding happens only on the embedded path, so a Node host (tests,
 * `next dev`, Docker, Azure) never pays for it.
 *
 * `node:zlib` is synchronous in workerd, which keeps installation inside
 * `register()` rather than making the first request race an async warmup.
 */
export function installEmbeddedData(): void {
  const globals = globalThis as Record<symbol, unknown>;
  if (globals[EMBEDDED_DATA_GLOBAL_KEY]) return;

  const json = gunzipSync(Buffer.from(EMBEDDED_DATA_GZIP_BASE64, "base64")).toString("utf8");

  Object.defineProperty(globalThis, EMBEDDED_DATA_GLOBAL_KEY, {
    value: JSON.parse(json) as EmbeddedDataBundle,
    configurable: true,
    enumerable: false,
    writable: false,
  });
}
